import numpy as np
import json

# Create 30x30 grid
grid = np.zeros((30, 30), dtype=int)

# 1. Hollow 5-frame (rows 1 and 25, cols 1 and 25)
for c in range(1, 26):
    grid[1, c] = 5
    grid[25, c] = 5
for r in range(1, 26):
    grid[r, 1] = 5
    grid[r, 25] = 5

# 2. Concentric pattern in interior (rows 2-24, cols 2-24)
center = (13, 13)
for y in range(2, 25):
    for x in range(2, 25):
        dist = max(abs(y - center[0]), abs(x - center[1]))
        if dist == 0:
            grid[y, x] = 0
        elif dist == 1:
            grid[y, x] = 5
        else:
            if dist % 2 == 0:
                grid[y, x] = 2
            else:
                grid[y, x] = 5

result = grid.tolist()

# Convert to JSON string for submission
json_str = json.dumps({"action": "submit", "grid": result})
print(json_str)

